function makeGradient(levels) {
  const data = new Uint8Array(levels.length * 4);
  levels.forEach((v, i) => { data[i * 4] = v; data[i * 4 + 1] = v; data[i * 4 + 2] = v; data[i * 4 + 3] = 255; });
