50: function part(parent, geo, mat, p = [0, 0, 0], s = [1, 1, 1], r = [0, 0, 0], outline = 0) {
51:   const m = new THREE.Mesh(geo, mat);
52:   m.position.set(...p); m.scale.set(...s); m.rotation.set(...r);
53:   m.castShadow = true; m.receiveShadow = false;
54:   parent.add(m);
55:   if (outline) {
56:     const o = new THREE.Mesh(geo, outline === 2 ? OUTLINE_MAT_SOFT : OUTLINE_MAT);
57:     o.scale.set(s[0] * (1 + outline * 0.018), s[1] * (1 + outline * 0.018), s[2] * (1 + outline * 0.018));
58:     o.position.copy(m.position); o.rotation.copy(m.rotation);
59:     o.castShadow = false; m.add(o);
60:     o.position.set(0, 0, 0); o.rotation.set(0, 0, 0);
61:   }
62:   return m;
63: }
64: function group(parent, p = [0, 0, 0]) { const g = new THREE.Group(); g.position.set(...p); parent.add(g); return g; }
