617: export function createTorii(scale = 1) {
618:   const g = new THREE.Group();
619:   const red = toon(0xb23a3a), dark = toon(0x2a1c1c);
620:   for (const sx of [-1, 1]) part(g, G.cyl, red, [sx * 1.6, 2.2, 0], [0.16, 4.4, 0.16], [0, 0, sx * 0.03], 1);
621:   part(g, G.box, red, [0, 3.6, 0], [4.3, 0.24, 0.3], [0, 0, 0], 1);
622:   part(g, G.box, red, [0, 4.25, 0], [5.0, 0.26, 0.4], [0, 0, 0], 1);
623:   part(g, G.box, dark, [0, 4.62, 0], [5.4, 0.14, 0.5]);
624:   part(g, G.box, dark, [0, 4.45, 0], [2.0, 0.3, 0.3]);
625:   g.scale.setScalar(scale);
626:   g.traverse(o => { if (o.isMesh) o.castShadow = true; });
627:   return g;
628: }
