193: export class ParticleSystem {
194:   constructor(scene, max = 1800) {
195:     this.max = max; this.cursor = 0;
196:     this.pos = new Float32Array(max * 3);
197:     this.col = new Float32Array(max * 3);
198:     this.size = new Float32Array(max);
199:     this.alpha = new Float32Array(max);
200:     this.vel = new Float32Array(max * 3);
201:     this.life = new Float32Array(max);
202:     this.maxLife = new Float32Array(max);
203:     this.grav = new Float32Array(max);
204:     this.drag = new Float32Array(max);
205:     this.baseSize = new Float32Array(max);
206:     this.geo = new THREE.BufferGeometry();
207:     this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
208:     this.geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
209:     this.geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
210:     this.geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
211:     this.geo.setDrawRange(0, max);
212:     this.mat = new THREE.ShaderMaterial({
213:       vertexShader: particleVert, fragmentShader: particleFrag,
214:       transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
215:       uniforms: { uScale: { value: 380 } }
216:     });
217:     this.points = new THREE.Points(this.geo, this.mat);
218:     this.points.frustumCulled = false;
219:     this.points.renderOrder = 5;
220:     scene.add(this.points);
221:     this.colors = new THREE.Color();
222:   }
223:   emit(o = {}) {
224:     const {
225:       pos = new THREE.Vector3(), count = 8, color = 0xffffff, spread = 0.4,
226:       speed = 2, speedVar = 1, life = 0.7, lifeVar = 0.3, size = 6, sizeVar = 3,
227:       gravity = 0, drag = 1.5, ring = false, dir = null, cone = 0
228:     } = o;
229:     const col = new THREE.Color(color);
230:     for (let i = 0; i < count; i++) {
231:       const idx = this.cursor; this.cursor = (this.cursor + 1) % this.max;
232:       const i3 = idx * 3;
233:       let dx, dy, dz;
234:       if (ring) {
235:         const a = Math.random() * TAU;
236:         dx = Math.cos(a); dz = Math.sin(a); dy = (Math.random() - 0.5) * 0.2;
237:       } else {
238:         dx = (Math.random() * 2 - 1); dy = (Math.random() * 2 - 1); dz = (Math.random() * 2 - 1);
239:         const l = Math.hypot(dx, dy, dz) || 1; dx /= l; dy /= l; dz /= l;
240:       }
241:       this.pos[i3] = pos.x + dx * spread * Math.random(); this.pos[i3 + 1] = pos.y + dy * spread * Math.random(); this.pos[i3 + 2] = pos.z + dz * spread * Math.random();
242:       const sp = speed + (Math.random() - 0.5) * speedVar;
243:       if (dir) {
244:         const angle = cone ? (Math.random() - 0.5) * cone : 0;
245:         const ca = Math.cos(angle), sa = Math.sin(angle);
246:         this.vel[i3] = (dir.x * ca - dir.z * sa) * sp;
247:         this.vel[i3 + 1] = (dir.y + (Math.random() - 0.5) * (cone ? 0.5 : 0.3)) * sp;
248:         this.vel[i3 + 2] = (dir.x * sa + dir.z * ca) * sp;
249:       } else {
250:         this.vel[i3] = dx * sp; this.vel[i3 + 1] = dy * sp + (o.up || 0); this.vel[i3 + 2] = dz * sp;
251:       }
252:       const lf = life + (Math.random() - 0.5) * lifeVar;
253:       this.life[idx] = lf; this.maxLife[idx] = lf;
254:       this.grav[idx] = gravity; this.drag[idx] = drag;
255:       this.baseSize[idx] = size + (Math.random() - 0.5) * sizeVar;
256:       this.size[idx] = this.baseSize[idx];
257:       const c2 = col.clone();
258:       if (o.color2) c2.lerp(new THREE.Color(o.color2), Math.random());
259:       c2.multiplyScalar(0.85 + Math.random() * 0.5);
260:       this.col[i3] = c2.r; this.col[i3 + 1] = c2.g; this.col[i3 + 2] = c2.b;
261:       this.alpha[idx] = 1;
262:     }
263:     this.geo.attributes.position.needsUpdate = true;
264:     this.geo.attributes.aColor.needsUpdate = true;
265:     this.geo.attributes.aSize.needsUpdate = true;
266:     this.geo.attributes.aAlpha.needsUpdate = true;
267:   }
268:   update(dt) {
269:     for (let i = 0; i < this.max; i++) {
270:       if (this.life[i] <= 0) { if (this.alpha[i] !== 0) this.alpha[i] = 0; continue; }
271:       this.life[i] -= dt;
272:       const t = Math.max(0, this.life[i] / this.maxLife[i]);
273:       this.alpha[i] = t * t;
274:       this.size[i] = this.baseSize[i] * (0.35 + t * 0.9);
275:       const i3 = i * 3;
276:       const dr = Math.exp(-this.drag[i] * dt);
277:       this.vel[i3] *= dr; this.vel[i3 + 1] = this.vel[i3 + 1] * dr + this.grav[i] * dt; this.vel[i3 + 2] *= dr;
278:       this.pos[i3] += this.vel[i3] * dt; this.pos[i3 + 1] += this.vel[i3 + 1] * dt; this.pos[i3 + 2] += this.vel[i3 + 2] * dt;
279:     }
280:     this.geo.attributes.position.needsUpdate = true;
281:     this.geo.attributes.aAlpha.needsUpdate = true;
282:     this.geo.attributes.aSize.needsUpdate = true;
283:   }
284: }
