303:       if (!this.keys.has(e.code)) this.just.add(e.code);
304:       this.keys.add(e.code);
305:     });
306:     addEventListener('keyup', e => this.keys.delete(e.code));
307:     addEventListener('blur', () => { this.keys.clear(); this.mouseButtons.clear(); this.joystick.active = false; this.joystick.x = 0; this.joystick.y = 0; });
308:     addEventListener('mousemove', e => {
309:       if (this.locked) { this.look.x += e.movementX; this.look.y += e.movementY; }
310:       else if (this.dragging) { this.look.x += e.movementX; this.look.y += e.movementY; }
311:     });
312:     this.canvas.addEventListener('mousedown', e => {
313:       if (e.button === 0 && !this.locked && !this.touchCapable) this.requestLock();
314:       this.dragging = true;
315:       this.mouseButtons.add(e.button); this.mouseJust.add(e.button);
316:     });
317:     addEventListener('mouseup', e => { this.dragging = false; this.mouseButtons.delete(e.button); });
318:     addEventListener('contextmenu', e => e.preventDefault());
319:     document.addEventListener('pointerlockchange', () => { this.locked = document.pointerLockElement === this.canvas; });
320:     // touch joystick
321:     const zone = document.getElementById('joystick-zone');
322:     const knob = document.getElementById('joystick-knob');
323:     if (zone) {
324:       const rect = () => zone.getBoundingClientRect();
325:       let pid = null;
326:       const update = e => {
327:         const r = rect(); const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
328:         let dx = e.clientX - cx, dy = e.clientY - cy;
329:         const max = r.width * 0.34; const l = Math.hypot(dx, dy);
330:         if (l > max) { dx = dx / l * max; dy = dy / l * max; }
331:         this.joystick.x = dx / max; this.joystick.y = dy / max; this.joystick.active = true;
332:         if (knob) knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
333:       };
334:       zone.addEventListener('pointerdown', e => { pid = e.pointerId; zone.setPointerCapture(pid); update(e); });
335:       zone.addEventListener('pointermove', e => { if (e.pointerId === pid) update(e); });
336:       const end = e => { if (e.pointerId === pid) { pid = null; this.joystick.active = false; this.joystick.x = 0; this.joystick.y = 0; if (knob) knob.style.transform = 'translate(-50%,-50%)'; } };
337:       zone.addEventListener('pointerup', end); zone.addEventListener('pointercancel', end);
338:     }
339:     document.querySelectorAll('[data-action]').forEach(btn => {
340:       const act = btn.dataset.action;
341:       btn.addEventListener('pointerdown', e => { e.preventDefault(); e.stopPropagation(); this.touchActions.add(act); this.touchJust.add(act); });
342:       const rel = e => { e.preventDefault(); this.touchActions.delete(act); };
343:       btn.addEventListener('pointerup', rel); btn.addEventListener('pointercancel', rel); btn.addEventListener('pointerleave', rel);
344:     });
345:   }
346:   requestLock() {
347:     if (this.touchCapable) return;
348:     try { this.canvas.requestPointerLock?.(); } catch (e) { /* noop */ }
349:   }
350:   exitLock() { if (document.pointerLockElement) document.exitPointerLock?.(); }
351:   down(code) { return this.keys.has(code); }
352:   pressed(code) { return this.just.has(code); }
353:   mouseDown(b = 0) { return this.mouseButtons.has(b); }
354:   mousePressed(b = 0) { return this.mouseJust.has(b); }
355:   consumeLook() { const l = { x: this.look.x, y: this.look.y }; this.look.x = 0; this.look.y = 0; return l; }
