351:   const torso = group(body, [0, 1.05, 0]);
352:   part(torso, G.cylTaper, toon(P.cloth), [0, 0.28, 0], [0.29 * broad, 0.56, 0.2 * broad], [0, 0, 0], 2);
353:   part(torso, G.box, toon(P.armor), [0, 0.32, 0.1], [0.4 * broad, 0.46, 0.14], [0.05, 0, 0]);
354:   part(torso, G.box, toon(P.accent), [0, 0.05, 0.18], [0.12, 0.16, 0.04]);
355:   if (isBrute) {
