408:       part(w, G.box, metal, [0, 0.34, 0], [0.055, 0.55, 0.02], [0, 0, i ? 0.16 : -0.16]);
409:       part(w, G.box, toon(P.accent), [0, 0.34, 0.01], [0.016, 0.4, 0.01], [0, 0, i ? 0.16 : -0.16]);
