142: export function createHero(id) {
143:   const def = CHARACTERS[id];
144:   const C = def.colors;
145:   const root = new THREE.Group();
146:   const body = group(root);
147:   const rig = { rock: root, body, def };
148: 
149:   // pelvis and legs
150:   const pelvis = group(body, [0, 0.95, 0]);
151:   part(pelvis, G.box, toon(C.cloth2), [0, 0, 0], [0.34, 0.22, 0.22], [0, 0, 0], 2);
152:   const legs = [];
153:   for (const sx of [-1, 1]) {
154:     const hip = group(body, [sx * 0.13, 0.95, 0]);
155:     part(hip, G.capsule, toon(C.cloth), [0, -0.27, 0], [0.085, 0.32, 0.085], [0, 0, 0], 2);
