158:     const boot = part(knee, G.box, toon(C.cloth2), [0, -0.44, 0.045], [0.15, 0.15, 0.33]);
159:     part(boot, G.box, toon(C.trim), [0, 0.05, 0.11], [1.02, 0.18, 0.28]);
160:     legs.push({ hip, knee, sx });
161:   }
162:   rig.legL = legs[0].hip; rig.legR = legs[1].hip; rig.kneeL = legs[0].knee; rig.kneeR = legs[1].knee;
163: 
164:   // torso
165:   const torso = group(body, [0, 1.06, 0]);
166:   part(torso, G.cylTaper, toon(C.cloth), [0, 0.28, 0], [0.28, 0.6, 0.19], [0, 0, 0], 2);
167:   part(torso, G.box, toon(C.cloth2), [0, 0.2, 0.135], [0.3, 0.34, 0.09], [0.06, 0, 0]);
168:   part(torso, G.box, toon(C.trim), [0, 0.02, 0.1], [0.36, 0.07, 0.12]);
169:   const gem = part(torso, G.octa, toon(C.accent, { emissive: C.accent, emissiveIntensity: 0.7 }), [0, 0.36, 0.19], [0.05, 0.075, 0.035]);
170:   rig.chestGem = gem;
171:   if (id === 'kael') {
172:     part(torso, G.box, toon(C.accent), [0, 0.34, -0.19], [0.34, 0.5, 0.06], [0, 0, 0]);
173:   }
174:   if (id === 'yumi') {
175:     part(torso, G.box, toon(C.trim), [0, 0.02, 0], [0.42, 0.11, 0.26]);
176:     part(torso, G.box, toon(C.accent), [-0.23, 0.12, -0.02], [0.12, 0.4, 0.09], [0, 0, 0.16]);
177:   }
178:   if (id === 'aria') {
179:     // robe skirt
180:     part(body, G.cone, toon(C.cloth), [0, 0.78, 0], [0.48, 0.72, 0.42], [0, 0, 0], 1);
181:     part(body, G.cone, toon(C.cloth2), [0, 0.72, 0], [0.52, 0.5, 0.46], [0, 0, 0]);
182:     part(body, G.torus, toon(C.trim), [0, 0.92, 0], [0.3, 0.3, 0.3], [Math.PI / 2, 0, 0]);
183:   }
184: 
185:   // head
186:   const neck = part(torso, G.cyl, toon(C.skin), [0, 0.65, 0], [0.07, 0.12, 0.07]);
187:   const head = group(torso, [0, 0.82, 0]);
188:   part(head, G.sphere, toon(C.skin), [0, 0, 0], [0.205, 0.225, 0.2], [0, 0, 0], 2);
189:   // jaw shape
190:   part(head, G.sphere, toon(C.skin), [0, -0.08, 0.03], [0.15, 0.15, 0.15]);
191:   eyes(head, C.eye);
192:   // brows
193:   for (const sx of [-1, 1]) part(head, G.box, toon(C.hair), [sx * 0.085, 0.085, 0.19], [0.075, 0.012, 0.01], [0, 0, sx * 0.12]);
194:   // mouth
195:   part(head, G.box, toon(0x8c4e55), [0, -0.105, 0.192], [0.05, 0.008, 0.01]);
196:   const hair = group(head, [0, 0.05, -0.02]);
197:   part(hair, G.sphere, toon(C.hair), [0, 0.03, -0.055], [0.225, 0.24, 0.21]);
198:   const hairPieces = [];
199:   if (id === 'kael') {
200:     for (let i = 0; i < 7; i++) {
201:       const a = -0.9 + i * 0.3;
202:       const h = part(hair, G.cone, toon(i % 2 ? C.hair : C.hair2), [Math.sin(a) * 0.16, 0.22, -0.03 + Math.cos(a) * 0.08], [0.07, 0.3 + Math.random() * 0.16, 0.07], [Math.cos(a) * 0.4, 0, -Math.sin(a) * 0.55]);
203:       hairPieces.push(h);
204:     }
205:     part(hair, G.cone, toon(C.hair), [-0.16, 0.03, 0.16], [0.06, 0.22, 0.06], [0.1, 0, 0.5]);
206:     part(hair, G.cone, toon(C.hair), [0.17, 0.02, 0.14], [0.05, 0.2, 0.05], [0.1, 0, -0.55]);
207:     // scarf
208:     const scarf = group(torso, [0, 0.66, 0]);
209:     const sp = [];
210:     for (let i = 0; i < 3; i++) sp.push(part(scarf, G.box, toon(C.accent), [0.02 + i * 0.02, -0.12 - i * 0.13, -0.12 - i * 0.05], [0.16, 0.18, 0.05], [0.2 + i * 0.1, 0, 0.06]));
211:     rig.scarf = sp;
212:     part(scarf, G.torus, toon(C.accent), [0, 0.03, 0], [0.17, 0.17, 0.2], [Math.PI / 2, 0, 0]);
213:   } else if (id === 'yumi') {
214:     part(hair, G.cone, toon(C.hair), [0, 0.12, -0.16], [0.12, 0.34, 0.12], [-0.5, 0, 0]);
215:     const pony = group(hair, [0, 0.08, -0.2]);
216:     for (let i = 0; i < 3; i++) hairPieces.push(part(pony, G.sphere, toon(C.hair2), [0, -0.12 - i * 0.16, -0.03 - i * 0.06], [0.09 - i * 0.012, 0.18, 0.08 - i * 0.01], [0.1, 0, 0]));
217:     part(hair, G.box, toon(C.accent), [0, 0.13, -0.14], [0.16, 0.04, 0.04], [0, 0, 0.2]);
218:     part(hair, G.cone, toon(C.hair), [-0.17, -0.06, 0.09], [0.05, 0.27, 0.05], [0.1, 0, 0.18]);
219:     part(hair, G.cone, toon(C.hair), [0.17, -0.06, 0.09], [0.05, 0.27, 0.05], [0.1, 0, -0.18]);
220:     rig.pony = pony;
221:     // ribbon
222:     part(torso, G.box, toon(C.accent), [0, 0.05, -0.2], [0.22, 0.16, 0.04], [0, 0, 0.4]);
223:   } else {
224:     // long hair
225:     for (const sx of [-1, 1]) {
226:       const t = group(hair, [sx * 0.16, 0.02, -0.06]);
227:       for (let i = 0; i < 3; i++) hairPieces.push(part(t, G.sphere, toon(i === 2 ? C.hair2 : C.hair), [0, -0.16 - i * 0.2, -0.02 - i * 0.02], [0.075, 0.22, 0.07], [0.05, 0, 0]));
228:     }
229:     part(hair, G.sphere, toon(C.hair), [0, -0.18, -0.1], [0.16, 0.3, 0.1]);
230:     // circlet
231:     part(head, G.torus, toon(C.accent, { emissive: C.accent, emissiveIntensity: 0.7 }), [0, 0.07, 0], [0.2, 0.2, 0.2], [Math.PI / 2, 0, 0]);
232:     part(head, G.octa, toon(C.accent, { emissive: C.accent, emissiveIntensity: 1 }), [0, 0.11, 0.19], [0.035, 0.055, 0.02]);
233:   }
234:   rig.hair = hair; rig.hairPieces = hairPieces;
235: 
236:   // arms
237:   const arms = [];
238:   for (const sx of [-1, 1]) {
239:     const sh = group(torso, [sx * 0.34, 0.55, 0]);
240:     part(sh, G.sphere, toon(C.cloth), [0, 0, 0], [0.11, 0.11, 0.11], [0, 0, 0], 2);
241:     part(sh, G.capsule, toon(C.cloth), [0, -0.2, 0], [0.07, 0.22, 0.07], [0, 0, 0], 2);
242:     const el = group(sh, [0, -0.4, 0]);
243:     part(el, G.capsule, toon(id === 'aria' ? C.cloth : C.skin), [0, -0.18, 0], [0.06, 0.2, 0.06]);
244:     if (id === 'aria') part(el, G.cone, toon(C.cloth2), [0, -0.13, 0], [0.16, 0.36, 0.16], [0, 0, 0]);
245:     const hand = group(el, [0, -0.4, 0]);
246:     part(hand, G.sphere, toon(C.skin), [0, 0, 0], [0.06, 0.075, 0.06]);
247:     arms.push({ sh, el, hand, sx });
248:   }
249:   rig.armL = arms[0].sh; rig.armR = arms[1].sh; rig.elbowL = arms[0].el; rig.elbowR = arms[1].el; rig.handL = arms[0].hand; rig.handR = arms[1].hand;
250: 
251:   // weapon
252:   const weaponParent = id === 'aria' ? rig.handR : rig.handR;
253:   const weapon = buildWeapon(def.weapon, C, weaponParent);
254:   weapon.position.set(0, 0, 0);
255:   rig.weapon = weapon;
256:   if (id === 'yumi') {
257:     const w2 = buildWeapon('dual', { ...C, accent: C.trim }, rig.handL);
258:     w2.scale.setScalar(0.92);
259:     rig.weapon2 = w2;
260:   }
261:   if (id === 'aria') {
262:     weapon.rotation.z = 0.2;
263:     const orb = new THREE.Group(); body.add(orb);
264:     for (let i = 0; i < 3; i++) {
265:       const o = part(orb, G.octa, toon(C.accent, { emissive: C.accent, emissiveIntensity: 1.5 }), [0, 0, 0], [0.045, 0.08, 0.045]);
266:       o.userData.phase = i / 3 * Math.PI * 2;
267:       if (i === 0) rig.orbA = o; else if (i === 1) rig.orbB = o; else rig.orbC = o;
268:     }
269:   }
270:   // feet aura ring
271:   const ring = new THREE.Mesh(new THREE.RingGeometry(0.45, 0.6, 32), new THREE.MeshBasicMaterial({ color: C.accent, transparent: true, opacity: 0.35, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
272:   ring.rotation.x = -Math.PI / 2; ring.position.y = 0.03; root.add(ring); rig.auraRing = ring;
273: 
274:   root.traverse(o => { if (o.isMesh) { o.castShadow = true; } });
275:   return rig;
276: }
