    state.xp -= 100 + (state.level - 1) * 35; state.level++;
    const maxHp = heroDef.hp + (state.level - 1) * 12;
    state.hp = Math.min(maxHp, state.hp + 25); state.stamina = heroDef.stamina + (state.level - 1) * 4;
