}
function useTonic() {
  if (!state.inventory.tonic) { toast('No tonics remaining', 'Visit the Wayfarer to stock up.'); return; }
  const max = heroDef.hp + (state.level - 1) * 12;
  if (state.hp >= max) { toast('Vitality full', 'Save the tonic for later.'); return; }
